<?php
namespace App\Filament\Resources\Parameters\Schemas; use Filament\Forms\Components\{Select,TextInput,Textarea}; use Filament\Schemas\Schema; class ParameterForm {public static function configure(Schema $schema):Schema{return $schema->components([TextInput::make('name')->required(),TextInput::make('parameter_key')->required(),Select::make('data_type')->options(array_combine(['number','currency','percentage','integer','boolean','text','json'],['Number','Currency','Percentage','Integer','Boolean','Text','JSON']))->required(),Select::make('scope')->options(array_combine(['global','segment','product','calculator','regulatory'],['Global','Segment','Product','Calculator','Regulatory']))->required(),TextInput::make('unit'),Textarea::make('description')->columnSpanFull()]);}}
